// Stream Processor Init
func (s *Stream) Process(ctx context.Context) error {
    for {
        select {
        case msg := <-s.input:
            enriched := s.enricher.Apply(msg)
            if err := s.sink.Write(enriched); err != nil {
                log.Error("sink_error", err)
            }
        case <-ctx.Done():
            return nil
        }
    }
}
